create table if not exists public.workflow(workflow_id bigint generated always as identity primary key,workflow_name text not null unique,target_module text not null,is_active boolean not null default true);
create table if not exists public.workflow_step(step_id bigint generated always as identity primary key,workflow_id bigint not null references public.workflow(workflow_id) on delete cascade,step_order integer not null check(step_order>0),step_name text not null,unique(workflow_id,step_order));
create table if not exists public.workflow_rule(rule_id bigint generated always as identity primary key,step_id bigint not null references public.workflow_step(step_id) on delete cascade,condition_field text not null,operator text not null,condition_value text not null);
create table if not exists public.workflow_action(action_id bigint generated always as identity primary key,step_id bigint not null references public.workflow_step(step_id) on delete cascade,action_type text not null,execution_payload text not null);
create table if not exists public.approval_matrix(matrix_id bigint generated always as identity primary key,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),department_id bigint references public.departments(department_id),transaction_type_id bigint not null references public.transaction_types(transaction_type_id),min_amount numeric(24,6) not null check(min_amount>=0),max_amount numeric(24,6) not null check(max_amount>=min_amount),approver_role_id bigint not null references public.roles(role_id));
create table if not exists public.approval(approval_id bigint generated always as identity primary key,transaction_id bigint not null references public."transaction"(transaction_id),current_step_id bigint not null references public.workflow_step(step_id),status text not null);
create table if not exists public.approval_log(log_id bigint generated always as identity primary key,approval_id bigint not null references public.approval(approval_id) on delete cascade,user_id bigint not null references public.users(user_id),action text not null,comments text,action_timestamp timestamptz not null default now());
do $$declare t text;begin foreach t in array array['workflow','workflow_step','workflow_rule','workflow_action','approval_matrix','approval','approval_log'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "workflow_select" on public.%I',t);execute format('drop policy if exists "workflow_insert" on public.%I',t);execute format('drop policy if exists "workflow_update" on public.%I',t);execute format('drop policy if exists "workflow_delete" on public.%I',t);execute format('create policy "workflow_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "workflow_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "workflow_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "workflow_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
